  exit 3
fi
base64 -d <<'T_EOF' | gunzip > "$ROOT/table.json"
H4sIAAAAAAAC/6XW3U6DMBQA4FdpMBqdm7C1UNC5FxElhdW5yNoF2kQz9+628ydY1rBabiiH01O+
